void mbd_gopen_56k::predict(const BallCandidates::PatchYUVClassified& patch, double meanBrightnessOffset)
{
	ASSERT(patch.size() == 16);

	for(size_t x=0; x < patch.size(); x++) {
		for(size_t y=0; y < patch.size(); y++) {
			// Add a custom brightness offset that depends on the dataset, if zero centering was used
			float value = (static_cast<float>((patch.data[patch.size() * x + y].pixel.y)) / 255.0f) + static_cast<float>(meanBrightnessOffset);
			in_step[y][x][0] = value;
		}
	}

	cnn(in_step);
}

double mbd_gopen_56k::getRadius() const {
	return scores[0];
}
Vector2d mbd_gopen_56k::getCenter() const {
	return Vector2d(scores[1], scores[2]);
}
double mbd_gopen_56k::getBallConfidence() const {
	return 1.0f;
}

